window.SHEIKH_ANSWERS["الرءوف"] = ['الرءوف هو الشديد الرحمة، الذي يوصل رحمته إلى الخلق في أبلغ وجه، قال تعالى: {إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ}. قال الغزالي في «المقصود الأسنى»: الرءوف هو المبالغ في الرحمة، فالرأفة أبلغ من الرحمة، لأنها رحمة مشوبة بترك الآفات وإزالة المؤذيات، والله رءوف بعباده يريد بهم اليسر ولا يريد بهم العسر، قال تعالى: {يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ}.', 'التخلق به هو أن يكون العبد رؤوفاً بعباد الله، رحيماً بهم، يوصل الخير إليهم، ولا يؤذيهم، ويشفق على الضعفاء والمساكين، قال تعالى: {وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ}. فالمتخلق بالرءوف يرفق بالخلق، ويحسن إليهم، ولا يكون قاسياً عليهم.', 'التعلق به هو مقام «التعلق بالرأفة الإلهية»، وهو أن يعلّق العبد قلبه برأفة الله به، فيطمئن إلى لطفه، ويستبشر بمعاملته، ولا ييأس من رحمته، ويتعلق بطلب الرأفة من الله في الشدائد، قال تعالى: {وَلَا تَيْأَسُوا مِنْ رَوْحِ اللَّهِ}. وهو تعلق يوجب الرجاء والطمأنينة.', 'التحقق به هو مقام «الفناء في شهود الرأفة»، وهو أن يشهد السالك رأفة الله به في جميع أحواله، فتمتلئ نفسه شكراً وطمأنينة، ويرى الله رؤوفاً به في السراء والضراء، فيتعلق به في كل شأن، ولا يخاف سواه، لأنه يعلم أن الله رءوف به لا يريد به إلا الخير. فإذا تحقق العبد بالرءوف صار رحيماً بالخلق، شكوراً لله.', 'خاصيته سكينة القلب، ودفع الهموم، وتيسير الأمور، وبلوغ الرحمة، وحسن العاقبة. فمن أكثر من ذكره (يا رءوف) بقلب حاضر، رزقه الله الرأفة بالخلق، ودفع عنه الآفات.', 'نعم، هو من الأسماء الجامعة. ذلك أن الرأفة تقتضي تمام الرحمة والإحسان والكرم، فالرءوف هو الرحيم المحسن الكريم الذي يريد بعباده اليسر. فهو يجمع صفات الرحمة والإحسان والكرم.', 'هو من أسماء الصفات. ذلك أن الرأفة صفة قائمة بالله تعالى دالة على كمال الرحمة، وهي من أسماء الصفات الدالة على معنى زائد على الذات. وإن كانت تظهر في الأفعال.', 'هو من أسماء الجمال بالذات. لما يورثه في قلب السالك من الأنس والطمأنينة والرجاء في لطف الله. فهو من أخص أسماء الجمال والأنس.', 'يُذكر مقروناً بالرحيم في قوله تعالى: {إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ}. والسر في هذا الاقتران أن الرأفة أبلغ الرحمة، فجمع بينهما في الإحسان الكامل إلى العباد.'];
window.SHEIKH_ANSWERS["مالك الملك"] = ['مالك الملك هو الذي له الملك كله، يتصرف في ملكه كيف يشاء، ويعطي الملك من يشاء وينزعه ممن يشاء، قال تعالى: {قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ}. قال الغزالي: مالك الملك هو المتصرف في ملكه تصرف المالك الواثق، الذي لا ينازعه في ملكه منازع، ولا يعارضه في تصرفه معارض، وقد اجتمع فيه معنيان: الملك وهو التصرف، والمالكية وهي الاستحقاق.', 'التخلق به هو أن يملك العبد نفسه عن هواها، ويكون مالكاً لأمره، لا تستعبده شهواته، ولا يستعبد غيره، قال تعالى: {قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ}. فالمتخلق بمالك الملك يملك زمام نفسه، ويكون حريصاً على قيادة أمره إلى طاعة الله.', 'التعلق به هو مقام «التعلق بالملك الإلهي»، وهو أن يعلّق العبد قلبه بأن الله مالك الملك، فيرجع إليه في كل طلب، ويرجو منه ما يرجو من المالك، ولا يخاف سواه، لأن من بيده الملك هو الله وحده. قال تعالى: {وَإِنْ يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ}.', 'التحقق به هو مقام «الفناء في شهود الملكية»، وهو أن يشهد السالك أن الملك كله لله، فيتخلص من التعلق بالملوك والخلق، ولا يرجو إلا الله، ولا يخاف إلا الله، ويرى كل تصرف في الملكوت لله وحده. فإذا تحقق العبد بمالك الملك صار قلبه ملكاً لله، لا يتأثر بمن زال ملكه ولا يستعبد بملك غيره.', 'خاصيته العزة، وعدم الذل للخلق، وقوة القلب، وقضاء الحوائج، ونيل الرفعة. فمن أكثر من ذكره (يا مالك الملك) بقلب حاضر، أعزه الله، ومكن له، وأغناه عن الخلق.', 'نعم، هو من الأسماء الجامعة. ذلك أن الملك يقتضي تمام القدرة والتصرف والعلم، فمالك الملك هو القادر العليم المدبر، الذي له التصرف في كل شيء. فهو يجمع صفات القدرة والعلم والتدبير.', 'هو من أسماء الصفات والأفعال. فالملك من حيث استحقاقه الذاتي راجع إلى الصفات، ومن حيث تصرفه في الملك بإيتاء الملك ونزعه فهو من أسماء الأفعال.', 'هو من أسماء الجلال غالباً. لما يورثه في قلب السالك من عظمة الله وإجلاله، ومن الرهبة من ملكه. وفيه من الجمال أن ملك الله يتضمن الرحمة والإحسان.', 'يُذكر مركباً مقروناً بالملك في قوله تعالى: {مَالِكِ يَوْمِ الدِّينِ} و{تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ}. والسر في هذا التركيب أن الملك المقصود به ملك الله الخاص، فلا ملك حقيقي إلا ملكه.'];
window.SHEIKH_ANSWERS["ذو الجلال والإكرام"] = ['ذو الجلال والإكرام هو الجامع للعظمة والمجد، مع الكرامة والعطاء، قال تعالى: {تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلَالِ وَالْإِكْرَامِ}. قال الغزالي: ذو الجلال والإكرام هو الذي اجتمع له الجلال والإكرام، فالجلال عظمته التي لا تقاس، والإكرام كرمه الذي لا ينفد، فهو العظيم في ذاته الجليل في صفاته، الكريم الذي يكرم أولياءه ويعطيهم.', 'التخلق به هو أن يجمع العبد بين الجلال في أخلاقه والإكرام في معاملته، فيكون مهيباً محترماً، كريماً جواداً، قال تعالى: {وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ}. فالمتخلق بذو الجلال والإكرام يكون له من الوقار ما يهابه الناس، ومن الكرم ما يحببه إليهم.', 'التعلق به هو مقام «التعلق بجلال الله وإكرامه»، وهو أن يعلّق العبد قلبه بجلال الله فيخشاه، وبإكرامه فيرجوه، فيجمع بين الخوف والرجاء، ويتعلق بالله الحي القيوم ذي الجلال والإكرام. وهو تعلق يوجب توازن الخوف والرجاء.', 'التحقق به هو مقام «الفناء في شهود الجلال والإكرام»، وهو أن يشهد السالك جلال الله في كل شيء وإكرامه لعباده، فتمتلئ نفسه تعظيماً لله وشكراً له، ويرى الله جليلاً لا يليق به النقص، كريماً لا يليق به المنع. فإذا تحقق العبد بذو الجلال والإكرام صار وقوراً في نفسه، كريماً مع الخلق.', 'خاصيته تعظيم الله في القلب، ونيل الكرامة، والوقار في الخلق، وقضاء الحوائج. فمن أكثر من ذكره (يا ذا الجلال والإكرام) بقلب حاضر، عظّم الله في قلبه، وأكرمه بفضله.', 'نعم، هو من الأسماء الجامعة. ذلك أن الجلال يقتضي العظمة والكمال، والإكرام يقتضي الكرم والرحمة، فاجتمع فيهما صفات العظمة والكمال والكرم، فهو اسم جامع لمعاني الكمال.', 'هو من أسماء الذات والصفات. فالجلال من أسماء الذات الدالة على عظمة الله، والإكرام من أسماء الصفات الدالة على كرمه. وهو من أسماء الله التي تجمع بين الذات والصفات.', 'هو من أسماء الجلال والجمال معاً. لما يورثه في قلب السالك من الخشية من جلال الله، والرجاء في إكرامه، فيجمع الخوف والرجاء في مقام واحد.', 'يُذكر مركباً مقروناً بين الجلال والإكرام في قوله تعالى: {تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلَالِ وَالْإِكْرَامِ}. والسر في هذا التركيب أن العظمة والكرم متلازمان، فلا عظمة تامة إلا بكرم، ولا كرم كامل إلا مع عظمة.'];
window.SHEIKH_ANSWERS["المقسط"] = ['المقسط هو العادل في حكمه، الذي يقسط بين عباده بالحق، قال تعالى: {وَاللَّهُ يَقْسِطُ وَهُوَ خَيْرُ الْفَاصِلِينَ}، وقال: {قَائِمًا بِالْقِسْطِ}. قال الغزالي: المقسط هو الذي يقضي بالحق وينصف من الظالم، والعادل الذي لا يظلم أحداً، فقسمة الله للرزق والأعمال والأحكام كلها بالعدل والحكمة، لا جور فيها ولا ميل.', 'التخلق به هو أن يعدل العبد بين الناس، ويكون منصفاً في أقواله وأحكامه، قال تعالى: {وَإِذَا حَكَمْتُمْ بَيْنَ النَّاسِ أَنْ تَحْكُمُوا بِالْعَدْلِ}. فالمتخلق بالمقسط يكون عادلاً في بيته ومعاملاته، منصفاً للمظلوم، لا يظلم أحداً.', 'التعلق به هو مقام «التعلق بالعدل الإلهي»، وهو أن يعلّق العبد قلبه بأن الله يقسط بالحق، فيرضى بقضائه، ولا يجزع من عدله، ويستريح إلى أن الله سينصفه من الظالمين، قال تعالى: {إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ}. وهو تعلق يوجب الطمأنينة والرضا.', 'التحقق به هو مقام «الفناء في شهود العدل»، وهو أن يشهد السالك عدل الله في كل شيء، فلا يعترض على حكم الله، ويرى كل قسمة عادلة، فيسلم قلبه لله، ولا يظلم أحداً من الخلق. فإذا تحقق العبد بالمقسط صار عادلاً في نفسه، منصفاً مع الخلق، راضياً بقضاء الله.', 'خاصيته العدل في القضاء، والإنصاف، وطمأنينة القلب، وحفظ الحقوق. فمن أكثر من ذكره (يا مقسط) بقلب حاضر، عدل الله بينه وبين الناس، وأعانه على العدل.', 'نعم، هو من الأسماء الجامعة. ذلك أن القسط يقتضي تمام العلم بأحكام الخلق، وتمام الحكمة في التقدير، وتمام العدل في المجازاة. فهو يجمع صفات العلم والحكمة والعدل.', 'هو من أسماء الأفعال. ذلك أن القسط من أفعال الله المتعلقة بالحكم بين الخلق، وهو من أسماء الأفعال الدالة على العدل في الفصل بين العباد.', 'هو من أسماء الجلال غالباً. لما يورثه في قلب السالك من خشية الله العادل، ومن الطمأنينة إلى عدله. وفيه من الجمال أن عدله تعالى يتضمن الرحمة والإنصاف.', 'يُذكر مقروناً بالعدل والحق في آيات كثيرة. والسر في هذا المعنى أن القسط هو العدل بعينه، فمن كان مقسطاً كان عادلاً في حكمه لا يجور.'];
window.SHEIKH_ANSWERS["الجامع"] = ['الجامع هو الذي يجمع الخلق ليوم الجمع، ويجمع الأشياء المتفرقة من شؤون خلقه، قال تعالى: {رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَا رَيْبَ فِيهِ}. قال الغزالي: الجامع هو الذي يجمع المتفرقات، ويجمع الخلائق ليوم الجمع، ويجمع للعبد ما تفرق من شأنه، وهو الذي يجمع المتقين في دار كرامته، والمسيئين في دار عقوبته.', 'التخلق به هو أن يجمع العبد همته، فلا يشتت قلبه بين الأغيار، ويجمع على الطاعة، ويجمع ما تفرق من وقته في العبادة، قال تعالى: {وَأَقِمِ الصَّلَاةَ لِذِكْرِي}. فالمتخلق بالجامع يكون جمع الهمة، مجتمع القلب، لا يتشتت في أموره.', 'التعلق به هو مقام «التعلق بجمع الله»، وهو أن يعلّق العبد رجاءه بأن الله يجمع له ما تفرق من شأنه، ويجمع له أهله وماله في الخير، ويجمعه يوم القيامة مع المتقين، فيتعلق بطلب الجمع الحسن من الله. وهو تعلق يوجب الدعاء بحسن الجمع.', 'التحقق به هو مقام «الفناء في شهود الجمع»، وهو أن يشهد السالك أن الله يجمع كل شيء، وأنه سيجمع الخلق ليوم لا ريب فيه، فيعمل لذلك اليوم، ويهتم بأمر الجمع يوم القيامة، قال تعالى: {ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ}. فإذا تحقق العبد بالجامع صار عمله كله للآخرة، وقلبه مجتمعاً على الله.', 'خاصيته جمع الهمة، وإتقان الأعمال، وجمع الشمل، وبلوغ الاجتماع في الخير. فمن أكثر من ذكره (يا جامع) بقلب حاضر، جمع الله له شمله، وهداه إلى اجتماع القلب على الطاعة.', 'نعم، هو من الأسماء الجامعة. ذلك أن الجمع يقتضي تمام العلم بالمتفرقات، وتمام القدرة على جمعها، وتمام الحكمة في تدبيرها. فهو يجمع صفات العلم والقدرة والحكمة.', 'هو من أسماء الأفعال. ذلك أن الجمع من أفعال الله المتعلقة بجمع الخلق وضم المتفرقات، وهو من أسماء الأفعال الدالة على الحشر والجمع.', 'هو من أسماء الجلال والكمال معاً. لما يورثه في قلب السالك من ذكر يوم الجمع والخوف من الحساب، ومن الطمأنينة إلى جمع الله له أموره. وفيه من الجمال أن جمع الله للمؤمنين في الجنة رحمة.', 'يُذكر مقروناً بالحشر في قوله تعالى: {رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَا رَيْبَ فِيهِ}. والسر في هذا المعنى أن الجمع الذي وعد الله به هو يوم الحشر، فمن كان جامعاً للناس كان قادراً على بعثهم وحشرهم.'];
