window.SHEIKH_ANSWERS["الغني"] = ['الغني هو الذي استغنى عن كل شيء، وكل شيء محتاج إليه، قال تعالى: {وَاللَّهُ الْغَنِيُّ وَأَنْتُمُ الْفُقَرَاءُ}. قال الغزالي في «المقصود الأسنى»: الغني هو الذي لا يفتقر إلى شيء أصلاً، وهو الغني بذاته عن كل ما سواه، وجميع الموجودات مفتقرة إليه، فهو الغني الذي لا تنفد خزائنه، ولا تنقص عطاياه.', 'التخلق به هو أن يستغني العبد بالله عن الخلق، فلا يسأل إلا الله، ولا يرغب إلا في الله، ويكون غنياً بنفسه عن طمع الخلق، قال تعالى: {وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ}. فالمتخلق بالغني يقطع الطمع عن الخلق، ويغني قلبه بالله عن سؤال الناس.', 'التعلق به هو مقام «التعلق بالغنى المطلق»، وهو أن يعلّق العبد رجاءه بالله الغني، فيعلم أن كل غنى من الله، وأن الله يغني من يشاء، فيتعلق به في طلب الغنى، ويستغني به عن الخلق، قال تعالى: {يَا أَيُّهَا النَّاسُ أَنْتُمُ الْفُقَرَاءُ إِلَى اللَّهِ}. وهو تعلق يوجب قطع الطمع من الخلق.', 'التحقق به هو مقام «الفناء في شهود الغنى»، وهو أن يشهد السالك أن الله هو الغني المطلق، وأن العبد فقير إليه في كل حال، فلا يرى لنفسه غنى، ولا يرى لغير الله إغناء، فيستغني بالله عن الخلق، ويفنى عن شهود الحاجة إلى غير الله. فإذا تحقق العبد بالغني صار غنياً بالله، غير محتاج إلى الخلق، راضياً بقسم الله.', 'خاصيته الغنى عن الخلق، وقضاء الحوائج، وقطع الطمع، وعزة النفس. فمن أكثر من ذكره (يا غني) بقلب حاضر، أغناه الله، وجعل غناه في قلبه، وحفظه من ذل الفقر.', 'نعم، هو من الأسماء الجامعة. ذلك أن الغنى يقتضي تمام الكمال والقدرة، فالغني هو القادر العليم الذي لا يحتاج إلى شيء، ويحتاج إليه كل شيء. فهو يجمع صفات الكمال كلها.', 'هو من أسماء الذات والصفات. فالغنى صفة ذاتية لله، وهو من أسماء الذات لكونه غنياً بذاته، ومن أسماء الصفات لأنه يوصف به على الدوام.', 'هو من أسماء الجلال والكمال معاً. لما يورثه في قلب السالك من عظمة الله الغني، ومن الطمأنينة إليه. وفيه من الجمال أن غنى الله يتضمن الكرم والجود.', 'يُذكر مقروناً بالحميد في قوله تعالى: {وَاللَّهُ الْغَنِيُّ الْحَمِيدُ}. والسر في هذا الاقتران أن الغني الذي لا يحتاج إلى الحمد يستحقه بذاته، فهو غني عن الخلق حميد في ذاته.'];
window.SHEIKH_ANSWERS["المغني"] = ['المغني هو الذي يغني من يشاء من عباده، ويعطيهم ما يستغنون به، قال تعالى: {وَأَنَّهُ هُوَ أَغْنَى وَأَقْنَى}. قال الغزالي: المغني هو الذي يغني الخلق بما يصل إليهم من الأرزاق والأموال، فيجعل الغنى لعباده، ويوصل إليهم أسباب الكفاية، قال تعالى: {وَإِنْ مِنْ شَيْءٍ إِلَّا عِنْدَنَا خَزَائِنُهُ}.', 'التخلق به هو أن يسعى العبد في إغناء المحتاجين من الخلق، ويعطي من سأله، ويواسي الفقراء، قال تعالى: {وَآتَى الْمَالَ عَلَى حُبِّهِ ذَوِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينَ}. فالمتخلق بالمغني يغني الناس بما يملك، ولا يبخل عن إغناء محتاج.', 'التعلق به هو مقام «التعلق بالإغناء الإلهي»، وهو أن يعلّق العبد رجاءه بأن الله يغنيه، فيسأل الله الغنى، ويتعلق بطلب الإغناء من الله وحده، ولا يطلب الغنى من الخلق، قال تعالى: {قُلْ مَنْ بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ}. وهو تعلق يوجب سؤال الله الغنى.', 'التحقق به هو مقام «الفناء في شهود الإغناء»، وهو أن يشهد السالك أن الغنى والفقر بيد الله وحده، فيرضى بما أعطاه الله، ويشكر على الإغناء، ويسأل الله الغنى الحقيقي الذي هو غنى القلب عن الخلق. فإذا تحقق العبد بالمغني صار غنياً بالله، مواسياً للخلق، شاكراً لله.', 'خاصيته سعة الرزق، وقضاء الحوائج، وكفاية الهموم، والعز عن الخلق. فمن أكثر من ذكره (يا مغني) بقلب حاضر، أغناه الله عن الخلق، وسهل له أسباب الرزق.', 'نعم، هو من الأسماء الجامعة. ذلك أن الإغناء يقتضي تمام العلم بمصالح العباد، وتمام القدرة على الإعطاء، وتمام الكرم في البذل. فهو يجمع صفات العلم والقدرة والكرم.', 'هو من أسماء الأفعال. ذلك أن الإغناء من أفعال الله المتعلقة بخلقه، وهو من أسماء الأفعال الدالة على إعطاء الغنى ودفع الفقر.', 'هو من أسماء الجمال غالباً. لما يورثه في قلب السالك من الرجاء في إغناء الله، ومن الأمل في فضله. وفيه من الجلال أن الله هو الذي يغني ويفقر بإرادته.', 'يُذكر مقروناً بالغني في المعنى، قال تعالى: {وَأَنَّهُ هُوَ أَغْنَى وَأَقْنَى}. والسر أن الغني من صفات الذات، والمغني من الأفعال، فمن كان غنياً بذاته أغنى غيره بفضله.'];
