window.SHEIKH_ANSWERS["المانع"] = ['المانع هو الذي يمنع ما يشاء من خلقه، ويمنع عطاءه عن من يشاء لحكمة، قال تعالى: {مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُ مِنْ بَعْدِهِ}. قال الغزالي: المانع هو الذي يمنع العطاء عن من يشاء بحكمته، ويمنع الضر عن عباده، ويمنع عن العبد ما لا مصلحة له فيه، فمنعه حماية وحكمة لا بخلاً.', 'التخلق به هو أن يمنع العبد نفسه عن المحارم، ويمنع جوارحه عن الآثام، ويمنع لسانه عن الكذب والغيبة، قال تعالى: {وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ}. فالمتخلق بالمانع يمنع نفسه عن المعاصي، ويمنع غيره عن الضرر.', 'التعلق به هو مقام «التعلق بالمنع الإلهي»، وهو أن يعلّق العبد قلبه بأن المنع والعطاء بيد الله، فيرضى بمنع الله، ويعلم أن منع الله حكمة ومصلحة، ولا ييأس من فضل الله إذا مُنع، قال تعالى: {وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ}. وهو تعلق يوجب الرضا بقضاء الله.', 'التحقق به هو مقام «الفناء في شهود المنع»، وهو أن يشهد السالك أن المنع والعطاء بيد الله وحده، فلا يعترض على منع الله، ولا يحزن على ما مُنع منه، ويرى في المنع حكمة ولطفاً، قال تعالى: {وَأَنْتُمْ لَا تَمْلِكُونَ لَأَنْفُسِكُمْ ضَرًّا وَلَا نَفْعًا}. فإذا تحقق العبد بالمانع صار راضياً بقسم الله، صابراً على حرمانه.', 'خاصيته الحفظ من الشرور، والوقاية من المضار، وضبط النفس عن الآثام. فمن أكثر من ذكره (يا مانع) بقلب حاضر، حماه الله من المضار، ووقاه شرور النفس والعدو.', 'نعم، هو من الأسماء الجامعة. ذلك أن المنع يقتضي تمام العلم بالمصالح والمفاسد، وتمام الحكمة في التقدير، وتمام الرحمة في الحماية. فهو يجمع صفات العلم والحكمة والرحمة.', 'هو من أسماء الأفعال. ذلك أن المنع من أفعال الله المتعلقة بخلقه وتدبيره، وهو من أسماء الأفعال الدالة على منع الضر وجلب الخير.', 'هو من أسماء الجلال غالباً. لما يورثه في قلب السالك من الخشية من منع الله، ومن الخضوع لقضائه. وفيه من الجمال أن منع الله حماية ورحمة لا بخلاً.', 'يُذكر مقروناً بالعطاء في المعنى، قال تعالى: {مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُ}. والسر أن المنع والعطاء متقابلان، فمن ملك العطاء ملك المنع، وكلاهما بحكمته.'];
window.SHEIKH_ANSWERS["الضار"] = ['الضار هو الذي يضر من يشاء بحكمته وعدله، ويسلط الضر على من يستحقه، قال تعالى: {قُلْ لَا أَمْلِكُ لِنَفْسِي ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَاءَ اللَّهُ}. قال الغزالي: الضار هو الذي يقدر الضر ويخلقه على من يشاء، ليس بمعنى أنه ظالم، بل هو العادل الحكيم الذي يجري الضر بمقتضى حكمته، وقد جعل ذلك من تمام كماله، فلا ولي يعصم من ضره إلا هو.', 'التخلق به هو أن يدفع العبد الضر عن نفسه وعن غيره، ويتجنب ما يضر، ولا يضر أحداً من الخلق، قال تعالى: {وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا}. فالمتخلق بالضار يتوقى الضر، ولا يؤذي أحداً، ويدفع الأذى عن الناس.', 'التعلق به هو مقام «التعلق باللجوء إلى الله من الضر»، وهو أن يعلّق العبد قلبه بأن الضر والنفع بيد الله وحده، فلا يخاف ضرر الخلق، ولا يأمن ضر الله، ويلجأ إلى الله في دفع الضر، قال تعالى: {وَإِذَا مَسَّكَ الضُّرُّ فَإِلَيْهِ تَجْأَرُونَ}. وهو تعلق يوجب الخوف واللجوء إلى الله.', 'التحقق به هو مقام «الفناء في شهود الضر والنفع»، وهو أن يشهد السالك أن كل ضر ونفع من الله وحده، فلا يعتمد على غيره في دفع الضر، ولا يأمن مكر الله، ويستقيم على طاعة الله خوفاً من ضره ورجاءً في نفعه، قال تعالى: {فَلَا تَأْمَنُوا مَكْرَ اللَّهِ}. فإذا تحقق العبد بالضار صار خائفاً من الله، لاجئاً إليه في السراء والضراء.', 'خاصيته الحذر من معاصي الله، والوقاية من الضر، واللجوء إلى الله في الشدائد. فمن أكثر من ذكره (يا ضار) بقلب حاضر، حفظه الله من الضر، وعصمه من الشرور.', 'نعم، هو من الأسماء الجامعة. ذلك أن الضر يقتضي تمام العدل والحكمة والقدرة، فالضار هو العادل الحكيم القادر الذي يجري الأمور بمقتضى حكمته. فهو يجمع صفات العدل والحكمة والقدرة.', 'هو من أسماء الأفعال. ذلك أن الضر من أفعال الله المتعلقة بخلقه وتقديره، وهو من أسماء الأفعال الدالة على إيصال الضر لمن يستحق بحكمته.', 'هو من أسماء الجلال غالباً. لما يورثه في قلب السالك من الخوف والخشية من الله، ومن الحذر من عذابه. وفيه من الكمال أن ضر الله مقرون بالعدل لا بالظلم.', 'يُذكر مقروناً بالنافع في المعنى، قال تعالى: {قُلْ لَا أَمْلِكُ لِنَفْسِي ضَرًّا وَلَا نَفْعًا}. والسر أن الضر والنفع متقابلان يدلان على كمال التصرف، فمن ملك الضر ملك النفع، وكلاهما بإرادته وحكمته.'];
window.SHEIKH_ANSWERS["النافع"] = ['النافع هو الذي يوصل النفع إلى من يشاء من خلقه، ويعمهم برحمته وخيره، قال تعالى: {قُلْ كُلٌّ مِنْ عِنْدِ اللَّهِ}. قال الغزالي: النافع هو الذي يوصل النفع إلى من يشاء، وقد جعل الله سعادة العباد في هذه الدار والآخرة من نفعه، فلا نافع في الحقيقة إلا الله، وإنما النفع من غيره بإذنه.', 'التخلق به هو أن يكون العبد نافعاً للناس، يفيدهم بعلمه وماله وجاهه، قال صلى الله عليه وسلم: «خير الناس أنفعهم للناس». فالمتخلق بالنافع يسعى في مصالح الخلق، وينفعهم بما يملك من علم ونصح ودعاء.', 'التعلق به هو مقام «التعلق بالنفع الإلهي»، وهو أن يعلّق العبد رجاءه بأن الله ينفعه، فيسأل الله النفع، ويتعلق بطلب الخير من الله وحده، ويعلم أن كل نفع من الله، قال تعالى: {وَإِنْ يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ}. وهو تعلق يوجب سؤال الله النفع في الدين والدنيا.', 'التحقق به هو مقام «الفناء في شهود النفع»، وهو أن يشهد السالك أن كل نفع من الله وحده، فيشكر الله على النعم، ويرى النفع كله من الله، وينفع الخلق بتوفيقه، قال تعالى: {وَمَا بِكُمْ مِنْ نِعْمَةٍ فَمِنَ اللَّهِ}. فإذا تحقق العبد بالنافع صار نافعاً للناس، شاكراً لله.', 'خاصيته نفع الله له في دينه ودنياه، وقضاء الحوائج، وبقاء الذكر الحسن. فمن أكثر من ذكره (يا نافع) بقلب حاضر، نفعه الله في دينه ودنياه، وجعل له أثراً طيباً في الخلق.', 'نعم، هو من الأسماء الجامعة. ذلك أن النفع يقتضي تمام الرحمة والكرم والقدرة، فالنافع هو الرحيم الكريم القادر الذي يوصل الخير لمن يشاء. فهو يجمع صفات الرحمة والكرم والقدرة.', 'هو من أسماء الأفعال. ذلك أن النفع من أفعال الله المتعلقة بخلقه، وهو من أسماء الأفعال الدالة على إيصال الخير والمنافع إلى العباد.', 'هو من أسماء الجمال غالباً. لما يورثه في قلب السالك من الرجاء في نفع الله، والأمل في فضله. وفيه من الجلال أن النفع بيد الله وحده.', 'يُذكر مقروناً بالضار في المعنى، قال تعالى: {قُلْ لَا أَمْلِكُ لِنَفْسِي ضَرًّا وَلَا نَفْعًا}. والسر أن النفع والضر متقابلان، فمن ملك أحدهما ملك الآخر، وكلاهما بحكمة الله.'];
