window.SHEIKH_ANSWERS["النور"] = ['النور هو الذي ينوّر السموات والأرض بالهداية، وهو الذي أشرقت به الظلمات، قال تعالى: {اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ}. قال الغزالي في «المقصود الأسنى»: النور في حق الله هو الظاهر بنفسه المظهر لغيره، فهو الذي يهدي أهل السموات والأرض، وبهدايته اهتدوا، وبمعرفته تنوروا، وهو نور على نور، تتراءى له الظلمات فلا تخفى عليه خافية.', 'التخلق به هو أن ينوّر العبد قلبه بالإيمان، ولسانه بالذكر، وعمله بالصالحات، قال تعالى: {أَوَمَنْ كَانَ مَيْتًا فَأَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ فِي النَّاسِ}. فالمتخلق بالنور يلازم ذكر الله، فتشرق به أنوار القلوب، ويكون نوراً لمن حوله بالهداية والنصح.', 'التعلق به هو مقام «التعلق بنور الله»، وهو أن يعلّق العبد رجاءه بنور الله يهديه، فيطلب من الله النور في قلبه وبصره وسمعه، قال تعالى: {قَالَ رَبِّ اشْرَحْ لِي صَدْرِي}. وهو تعلق يوجب الدعاء بطلب النور والهداية.', 'التحقق به هو مقام «الفناء في شهود النور»، وهو أن يشهد السالك أن الله نور السموات والأرض، فتتنور بصيرته، ويرى بنور الله، فلا يرى إلا الله، وتشرق فيه أنوار المعرفة، قال تعالى: {يَهْدِي اللَّهُ لِنُورِهِ مَنْ يَشَاءُ}. فإذا تحقق العبد بالنور صار قلبه نوراً بالمعرفة، وبصيرته نوراً بالمشاهدة.', 'خاصيته نور البصيرة، وهداية القلب، ودفع الظلمات، وبلوغ المعرفة. فمن أكثر من ذكره (يا نور) بقلب حاضر، نوّر الله قلبه وبصيرته، وأعانه على الرؤية الباطنة.', 'نعم، هو من الأسماء الجامعة. ذلك أن النور يقتضي تمام الوجود والظهور والهداية، فالنور هو الظاهر بنفسه المظهر لغيره، الجامع لصفات الوجود والهداية. فهو يجمع معاني الكمال كلها.', 'هو من أسماء الذات والصفات. فالنور في حق الله صفة ذاتية، وهو من أسماء الذات لكونه ظاهراً بذاته، ومن أسماء الصفات لأنه يهدي غيره بهدايته.', 'هو من أسماء الجمال غالباً. لما يورثه في قلب السالك من الأنس والراحة والطمأنينة، ومن نور البصيرة. وفيه من الجلال أن نور الله يحجب عنه أبصار المخلوقين.', 'يُذكر مقروناً بالهداية في قوله تعالى: {يَهْدِي اللَّهُ لِنُورِهِ مَنْ يَشَاءُ}. والسر أن النور يستلزم الهداية، فمن كان نوراً بنفسه كان هادياً لغيره.'];
window.SHEIKH_ANSWERS["الهادي"] = ['الهادي هو الذي يهدي عباده إلى الحق، ويوفقهم إلى الطريق المستقيم، قال تعالى: {إِنَّ رَبَّكَ هُوَ يَحْكُمُ بَيْنَهُمْ}، وقال: {وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ آمَنُوا إِلَى صِرَاطٍ مُسْتَقِيمٍ}. قال الغزالي: الهادي هو الذي يهدي العباد إلى معرفته وعبادته، ويرشدهم إلى مصالحهم في دنياهم وأخراهم، فهداية الله نوعان: هداية عامة بالإرشاد، وهداية خاصة بالتوفيق التي لا يحصل إلا بفضله.', 'التخلق به هو أن يهدي العبد نفسه إلى الحق، ويهدي غيره إلى الخير، ويكون دليلاً للناس على الصراط المستقيم، قال تعالى: {وَجَعَلْنَاهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا}. فالمتخلق بالهادي يلزم نفسه بالهدى، وينصح الخلق، ويدعوهم إلى الله بالحكمة والموعظة الحسنة.', 'التعلق به هو مقام «التعلق بالهداية الإلهية»، وهو أن يعلّق العبد رجاءه بأن الله يهديه، فيسأل الله الهداية في كل صلاة: {اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ}، ويتعلق بطلب التوفيق من الله، قال تعالى: {وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ}. وهو تعلق يوجب الافتقار إلى هداية الله.', 'التحقق به هو مقام «الفناء في شهود الهداية»، وهو أن يشهد السالك أن الهداية كلها من الله، فلا يرى لنفسه هداية، بل يرى التوفيق من الله وحده، فيسأله الهداية في كل حال، ويستقيم على الصراط المستقيم، قال تعالى: {فَاسْتَقِمْ كَمَا أُمِرْتَ}. فإذا تحقق العبد بالهادي صار مهتدياً هادياً، دليلاً للناس إلى الله.', 'خاصيته الهداية والتوفيق، وثبات القلب على الصراط، ونيل المعرفة. فمن أكثر من ذكره (يا هادي) بقلب حاضر، هداه الله إلى الصواب، وثبته على الصراط المستقيم.', 'نعم، هو من الأسماء الجامعة. ذلك أن الهداية تقتضي تمام العلم بمصالح العباد، وتمام الرحمة في التوفيق، وتمام القدرة على الإرشاد. فهو يجمع صفات العلم والرحمة والقدرة.', 'هو من أسماء الأفعال. ذلك أن الهداية من أفعال الله المتعلقة بخلقه، وهو من أسماء الأفعال الدالة على الإرشاد والتوفيق، وإن كان يستلزم صفة الرحمة.', 'هو من أسماء الجمال غالباً. لما يورثه في قلب السالك من الرجاء في هداية الله، والطمأنينة إلى توفيقه. وفيه من الجلال أن الهداية بيد الله وحده.', 'يُذكر مقروناً بالصراط المستقيم في قوله تعالى: {وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ آمَنُوا إِلَى صِرَاطٍ مُسْتَقِيمٍ}. والسر أن الهداية التامة تقتضي الوصول إلى الصراط المستقيم، فمن هداه الله صار على الصراط.'];
window.SHEIKH_ANSWERS["البديع"] = ['البديع هو الذي أبدع الخلق على غير مثال سابق، واخترعه اختراعاً، قال تعالى: {بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ}. قال الغزالي: البديع هو الذي لا يماثله شيء، ولا يسبقه في الخلق سابق، ولا يحتاج إلى آلة ولا أداة، فهو الذي أبدع الموجودات من العدم وأوجدها على غير مثال، فبديع السماوات والأرض هو خالقهما على غير مثال سبق.', 'التخلق به هو أن يكون العبد مبتكراً في طاعة الله، مجدداً في عبادته، لا يقف عند حد العادة، بل يفتح على قلبه أبواب الخير المتنوعة، قال تعالى: {فَاسْتَبِقُوا الْخَيْرَاتِ}. فالمتخلق بالبديع يجدد الطاعات، ولا يمل من أنواع العبادة.', 'التعلق به هو مقام «التعلق ببديع الصنع»، وهو أن يعلّق العبد قلبه بمشاهدة بديع صنع الله في الخلق، فيتفكر في خلق السماوات والأرض، ويرى عجائب قدرة الله، قال تعالى: {أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ}. وهو تعلق يوجب التفكر والاعتبار.', 'التحقق به هو مقام «الفناء في شهود البديعية»، وهو أن يشهد السالك أن الله هو البديع الخالق لكل شيء، فيشاهد صنع الله في كل مخلوق، ويرى كل شيء بديعاً من صنعه، ولا يرى في الوجود صنعة سوى صنعته، قال تعالى: {صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ}. فإذا تحقق العبد بالبديع صار مشاهداً لعجائب قدرة الله، متعجباً من بدائع خلقه.', 'خاصيته التجدد في العبادة، والتفكر في الخلق، وقوة المعرفة بالله. فمن أكثر من ذكره (يا بديع) بقلب حاضر، فتح الله له أبواب المعرفة والتفكر في خلقه.', 'نعم، هو من الأسماء الجامعة. ذلك أن البديعية تقتضي تمام العلم بتفاصيل الخلق، وتمام القدرة على الإيجاد من العدم، وتمام الحكمة في الإتقان. فهو يجمع صفات العلم والقدرة والحكمة.', 'هو من أسماء الأفعال. ذلك أن الإبداع من أفعال الله المتعلقة بخلق السماوات والأرض، وهو من أسماء الأفعال الدالة على الخلق والإيجاد من العدم.', 'هو من أسماء الجلال والجمال معاً. لما يورثه في قلب السالك من تعظيم قدرة الله، ومن المتعة في مشاهدة بدائع صنعه. فهو يجمع بين الرهبة والأنس.', 'يُذكر مقروناً بخلق السماوات والأرض في قوله تعالى: {بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ}. والسر أن الإبداع الخاص بعظمة السماوات والأرض، فمن أبدعهما كان على كل شيء قديراً.'];
window.SHEIKH_ANSWERS["الباقي"] = ['الباقي هو الذي لا يزول ولا يفنى، وهو الدائم الوجود الذي لا تنقطع صفاته، قال تعالى: {وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ}. قال الغزالي: الباقي هو الدائم الوجود أبداً، الذي لا يلحقه فناء ولا عدم، فكل شيء هالك إلا وجهه، قال تعالى: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ}. فهو الباقي بعد فناء خلقه، والدائم بعد زوال ملكه.', 'التخلق به هو أن يجعل العبد عمله باقياً لله، ويكثر من الباقيات الصالحات، قال تعالى: {وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِنْدَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا}. فالمتخلق بالباقي يعمل ما يبقى ثوابه، ويجعل همته في الخير الدائم.', 'التعلق به هو مقام «التعلق بالباقي»، وهو أن يعلّق العبد قلبه بالله الباقي، فيزهد في الدنيا الفانية، ويقبل على ما يبقى من الخير، قال تعالى: {مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللَّهِ بَاقٍ}. وهو تعلق يوجب الإعراض عن الفاني والإقبال على الباقي.', 'التحقق به هو مقام «الفناء عن الفاني»، وهو أن يشهد السالك أن كل شيء هالك إلا وجه الله، فتفنى عنه رؤية الفاني، ويثبت قلبه على الباقي، فلا يغتر بالدنيا، ولا يركن إلى ما يفنى، قال تعالى: {مَنْ كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا}. فإذا تحقق العبد بالباقي صار همه في البقاء، وعمله للدار الباقية.', 'خاصيته الزهد في الدنيا، والإقبال على الآخرة، ودوام العمل الصالح. فمن أكثر من ذكره (يا باقي) بقلب حاضر، أبقى الله له عمله، وجعل همه في البقاء عنده.', 'نعم، هو من الأسماء الجامعة. ذلك أن البقاء يقتضي تمام الكمال والغنى، فالباقي هو الدائم الكامل الغني، الذي لا يلحقه النقص ولا الفناء. فهو يجمع صفات البقاء والكمال والغنى.', 'هو من أسماء الذات. ذلك أن البقاء صفة ذاتية لله تدل على أبديته، وهو من أخص أسماء الذات لأنها تدل على بقاء الله وانفراده بالدوام.', 'هو من أسماء الجلال والكمال معاً. لما يورثه في قلب السالك من عظمة الله الدائم، ومن الطمأنينة إلى ما يبقى عنده. وفيه من الجمال أن بقاء الله يتضمن الرحمة للباقين.', 'يُذكر مقروناً بوجه الله في قوله تعالى: {وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ}. والسر أن وجه الله هو الذي يبقى بعد فناء كل شيء، فالبقاء الحقيقي لله وحده.'];
