window.SHEIKH_ANSWERS["الأحد"] = ['الأحد هو المنفرد بالوحدانية الذي لا نظير له ولا مثل، قال تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ}. قال الغزالي في «المقصود الأسنى»: الأحد هو الذي لا يتجزأ ولا ينقسم ولا يثنى، وهو المنفرد بالذات عن كل مشارك، والفرد الذي لا شريك له في ملكه ولا ند في ذاته، فوحدانية الله تقتضي نفي النظير والمثيل والكفؤ، كما قال تعالى: {وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ}.', 'التخلق به هو أن يوحد العبد ربه في ذاته وصفاته، فلا يرى له شبهاً ولا مثيلاً في خلقه، ولا يشرك به شيئاً، ويكون مخلصاً في عبوديته لله وحده، قال تعالى: {وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا}. فالمتخلق بالأحد يقطع قلبه عن الشرك الظاهر والخفي، ويجعل عبادته لله وحده.', 'التعلق به هو مقام «التعلق بالأحد الصمد»، وهو أن يعلّق العبد قلبه بالله وحده لا يشرك به في حاجته أحداً، فيلجأ إليه وحده في الشدائد، ولا يدعو إلا إياه، ولا يرغب إلا إليه، قال تعالى: {فَإِذَا رَكِبُوا فِي الْفُلْكِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ}. وهو تعلق يوجب صفاء التوحيد وكمال الإخلاص.', 'التحقق به هو مقام «الفناء في شهود الأحدية»، وهو أن يشهد السالك أحدية الله في ذاته وصفاته وأفعاله، فلا يرى في الوجود فاعلاً ولا مؤثراً إلا الله، ويفنى عن رؤية الأغيار، ويثبت قلبه على شهود الواحد الأحد، قال تعالى: {قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ}. فإذا تحقق العبد بالأحد صار موحداً في السر والعلانية، خالصاً في عبوديته.', 'خاصيته صفاء التوحيد، وخلوص القلب من الشرك الخفي، وطمأنينة القلب، وقوة اليقين. فمن أكثر من ذكره (يا أحد) بقلب حاضر، طهر الله قلبه من الشرك، وثبته على التوحيد الخالص.', 'نعم، هو من الأسماء الجامعة. ذلك أن الأحدية أصل التوحيد الذي تجتمع عليه سائر الأسماء والصفات، فمن كان أحداً في ذاته وصفاته وأفعاله فهو العليم القادر الغني، وهو المستحق للعبادة وحده. فهو من أخص أسماء الذات الجامعة.', 'هو من أسماء الذات. ذلك أن الأحدية صفة ذاتية لله تعالى تقتضي انفراده بذاته عن كل مشابه، وهي من أخص أسماء الذات، لا تتعلق بفعل من أفعاله، بل هي دالة على انفراده ونفي النظير عنه.', 'هو من أسماء الجلال والكمال معاً. لما يورثه في قلب السالك من عظمة الله المتفرد بذاته، ومن قوة اليقين بوحدانيته. وفيه من الجمال أن أحدية الله تقتضي كماله وسعة رحمته.', 'يُذكر مقروناً بالصمد في سورة الإخلاص: {قُلْ هُوَ اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ}. والسر في هذا الاقتران أن الأحد يفيد نفي الشريك في الذات، والصمد يفيد اتصافه بصفات الكمال، فتوحيد الذات والصفات لا يتم إلا باجتماعهما.'];
